import Navbar from "../components/Navbar";

import Sidebar from "../components/Sidebar";

export default function Attendance() {

  return (

    <div className="layout">

      <Sidebar />

      <div className="main">

        <Navbar />

        <div className="content">

          <h1>Attendance</h1>

          <div className="card">

            <h3>Attendance Module</h3>

            <p>
              Employee Attendance
              Management System
            </p>

          </div>

        </div>

      </div>

    </div>
  );
}
